from app.services import users


def handle_get_user(params: dict) -> tuple[int, dict]:
    raw = params.get("id")
    if not isinstance(raw, str) or not raw.isdigit():
        return 400, {"error": "invalid id"}
    user = users.get_user(int(raw))
    if user is None:
        return 404, {"error": "not found"}
    return 200, user


def _is_valid_email(email: str) -> bool:
    """Validate an email: one ``@``, a non-empty local part and a dotted domain."""
    local, at_sign, domain = email.partition("@")
    if not at_sign or "@" in domain:
        return False
    if not local:
        return False
    if "." not in domain:
        return False
    if domain.startswith(".") or domain.endswith("."):
        return False
    return True


def handle_email_available(params: dict) -> tuple[int, dict]:
    raw = params.get("email")
    if not isinstance(raw, str):
        return 400, {"error": "invalid email"}
    email = raw.strip()
    if not _is_valid_email(email):
        return 400, {"error": "invalid email"}
    return 200, {"available": users.email_available(email)}
